import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"Sync Engine 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/usage/why-sync-engine.md","filePath":"zh-Hans/usage/why-sync-engine.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/usage/why-sync-engine.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="sync-engine-是什么" tabindex="-1">Sync Engine 是什么 <a class="header-anchor" href="#sync-engine-是什么" aria-label="Permalink to “Sync Engine 是什么”">​</a></h1><p><strong>Sync Engine</strong> 是一个可以用模块扩展的 Obsidian 同步插件：只安装你需要的部分，笔记就能在你的设备之间保持同步。Sync Engine 核心经过数月的人工迭代和实战检验，可靠且高度优化。</p><p>实际使用中，你选择一个存储后端（例如你自己的 WebDAV 服务器），按需加入加密等高级功能，然后按下&quot;同步&quot;。你不用配置用不到的功能，也不会携带永远连不上的服务的代码。无论后端是什么，同步都保持快速和可靠。</p><p><strong>Sync Engine 由真实的人类维护者负责</strong>。虽然 Sync Engine 接受 AI 辅助的模块贡献，但 Sync Engine 核心（插件本身）严格由人类编写，拒绝任何&quot;氛围编程&quot;。它由许多巧妙而 AI 无法复刻的工程创新组成。</p><h2 id="类似的选择" tabindex="-1">类似的选择 <a class="header-anchor" href="#类似的选择" aria-label="Permalink to “类似的选择”">​</a></h2><p>同步一个 Obsidian 仓库有几种方式：</p><ul><li><strong><a href="https://obsidian.md/sync" target="_blank" rel="noreferrer">Obsidian Sync</a></strong> 是官方的零配置方案。如果你想一分钟内用上同步、又不介意月费，从它开始。</li><li><strong><a href="https://github.com/remotely-save/remotely-save" target="_blank" rel="noreferrer">Remotely Save</a></strong> 支持多种后端（S3、Dropbox、OneDrive、WebDAV），但按需付费，开发已停滞多年且存在稳定性问题。</li><li><strong><a href="https://github.com/vrtmrz/obsidian-livesync" target="_blank" rel="noreferrer">Self-hosted LiveSync</a></strong> 和 <strong><a href="https://github.com/haierkeys/obsidian-fast-note-sync" target="_blank" rel="noreferrer">Fast Note Sync</a></strong> 提供基于服务器的实时同步。如果你愿意搭建自己的服务器，它们工作得很好。</li><li><strong><a href="https://github.com/No-Instructions/Relay" target="_blank" rel="noreferrer">Relay</a></strong> 是托管的中继服务。方便，但你的笔记要经过你无法控制的基础设施。</li></ul><p>Sync Engine 填补的空档是：你想自己选择存储；你希望插件保持轻量，用不到的功能不被打包进来；你想要高度优化的同步，不比自建服务器慢。</p><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h2><p>Sync Engine 核心提供保证扩展性和性能所需的必要功能：</p><h3 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h3><ul><li>启动 / 定时 / 聚焦同步 / 保存即同步。</li><li>用 Glob 规则配置细粒度的同步策略（双向 / 镜像远端 / 镜像本地 / 不同步）。</li><li>冲突解决策略（保留两者 / 新者保留 / 保留远端 / 保留本地 / 跳过）。</li><li>速率 / 内存控制选项。</li><li>同步文件的创建 / 修改时间。</li><li>自定义请求头。</li><li>以上大部分功能都可以通过编写模块来扩展。</li></ul><h3 id="可扩展架构" tabindex="-1">可扩展架构 <a class="header-anchor" href="#可扩展架构" aria-label="Permalink to “可扩展架构”">​</a></h3><ul><li>你可以在自定义模块中添加后端、优化器、同步触发器、i18n 资源、决策策略、冲突策略、设置项和自定义文件处理，并调用一切可用的操作。</li><li>官方提供文档、AI agent skill 和带调试与测试工具的 SDK。</li><li>插件提供专门的模块发现与管理界面。</li><li>仓库接受任何遵守<a href="./contributing">贡献指南</a>的模块贡献。</li></ul><h3 id="激进优化" tabindex="-1">激进优化 <a class="header-anchor" href="#激进优化" aria-label="Permalink to “激进优化”">​</a></h3><ul><li>增量同步从不每次上传整个仓库。</li><li><a href="./../deep-dive/asymmetric-storage">锚定非对称存储</a>技术大幅加快同步。</li><li>实时同步使用缓存的远端状态，可以在毫秒内完成。</li><li><a href="./benchmark">基准测试显示日常同步比 Remotely Save 快约 <strong>100 倍</strong></a>。</li><li>顺畅处理拥有数千个文件的仓库。</li><li>高度优化的核心同步时序不浪费一毫秒。</li><li>可扩展的优化器插槽确保每个请求都针对你自己的服务做了优化。</li><li>详细的性能对比见<a href="./benchmark">性能基准测试</a>。</li></ul><h3 id="可用模块" tabindex="-1">可用模块 <a class="header-anchor" href="#可用模块" aria-label="Permalink to “可用模块”">​</a></h3><p><strong>后端</strong>：</p><ul><li><a href="./../deep-dive/modules/webdav">WebDAV</a>：标准 WebDAV 协议实现，兼容性久经实战。支持任何提供合规 WebDAV API 的后端。</li><li><a href="./../deep-dive/modules/s3">S3</a>：Amazon S3 与 S3 兼容对象存储，带优化的批量删除。</li><li><a href="./../deep-dive/modules/gdrive">Google Drive</a>：Google Drive 存储，带优化的授权流程。</li><li><a href="./../deep-dive/modules/dropbox">Dropbox</a>：Dropbox 存储，带优化的授权流程和批量远端操作。</li></ul><p><strong>功能</strong>：</p><ul><li><a href="./../deep-dive/modules/encryption">加密</a>：精心设计的加密，为跨后端同步特别强化了安全性。</li><li><a href="./../deep-dive/modules/smart-merge">智能合并</a>：由递归三方合并驱动的冲突解决策略。</li></ul><p><strong>翻译</strong>：</p><ul><li>原生英语</li><li>I18n 简体中文</li><li>I18n 繁體中文</li><li>I18n Русский</li></ul><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h2><p>开始使用 Sync Engine 很简单：</p><ol><li>从 Obsidian 插件商店下载并启用 <code>Sync Engine</code>。</li><li>打开&quot;模块管理&quot;页面，安装需要的翻译、后端和可选功能。</li><li>在设置界面填写云服务的必要信息。</li><li>从命令面板或侧边栏按钮开始你的第一次同步。</li><li>审查将要执行的同步任务。</li><li>点击&quot;确认&quot;，你的文件将以光速到达配置的后端。</li><li>在你的其他设备上安装 Sync Engine，并按第一台设备的方式配置。</li><li>如果一切正常，每次同步运行都会自动发现本地与远端的变更，并在两者之间同步文件。</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Sync Engine 要求最低 Obsidian v1.13.0。Android 或 iOS 设备的门槛是 Android System Webview 98 或 iOS 15.4。低于这些阈值的设备无法正常工作。</p></div><h2 id="开发" tabindex="-1">开发 <a class="header-anchor" href="#开发" aria-label="Permalink to “开发”">​</a></h2><p>如果你认为 Sync Engine 的基础功能不能满足需求、想要自定义，我们建议你开发一个 Sync Engine 模块，而不是另起一个插件：</p><ol><li>Sync Engine 高度优化且久经实战，在它之上开发可以为你节省大量测试和调试时间。</li><li>Sync Engine 提供官方 SDK 和清晰的文档，核心已有成熟的同步抽象，你不需要重复造轮子。</li><li>Sync Engine 的模块生态有乘数效应，你可以一边使用其他模块的功能，一边实现自己的功能，而不是把所有功能写进一个巨大的单体插件。</li></ol><p>关于如何开发模块，见<a href="./../development/develop-a-module">开发文档</a>。想向官方仓库贡献的话，见<a href="./contributing">贡献标准</a>。</p>`,31)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};